import{_ as t,c as e,o as n,ag as s}from"./chunks/framework.Cycwnjj0.js";const a="/assets/desired-comparison-table.7igqLrg8.webp",r="/assets/opened-table.B_PtTU_8.webp",i="/assets/dropdown-list-of-each-row.DvIRqmWf.webp",p="/assets/drag-_-drop_-add-new-row-and-delete-buttons.DB0DMcol.webp",g="/assets/appearance-setting-and-its-two-options.QduU_aTH.webp",c="/assets/compared-products-setting.DKi5VHud.webp",l="/assets/edit-compare-product-popup-page.BptHJb0T.webp",d="/assets/show-more-options-for-highlighting-the-products.Duq8ij_y.webp",u="/assets/update-_-preview-button.C3FeHCIK.webp",C=JSON.parse('{"title":"Customization Of Comparison Tables","description":"","frontmatter":{},"headers":[],"relativePath":"guide/amazon-comparison-tables/customization-of-comparison-tables.md","filePath":"guide/amazon-comparison-tables/customization-of-comparison-tables.md"}'),h={name:"guide/amazon-comparison-tables/customization-of-comparison-tables.md"};function m(b,o,w,f,y,_){return n(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="customization-of-comparison-tables" tabindex="-1">Customization Of Comparison Tables <a class="header-anchor" href="#customization-of-comparison-tables" aria-label="Permalink to &quot;Customization Of Comparison Tables&quot;">​</a></h1><p>AzonPress offers excellent customization features, making it easy to customize according to your needs. This article will guide you through <strong>Customizing Comparison Tables</strong> with <strong>AzonPress</strong> for <strong>Amazon products</strong> on your <strong>WordPress</strong> website.</p><h2 id="how-to-customize-a-comparison-table" tabindex="-1">How To Customize A Comparison Table <a class="header-anchor" href="#how-to-customize-a-comparison-table" aria-label="Permalink to &quot;How To Customize A Comparison Table&quot;">​</a></h2><p>To learn how to customize the information displayed in your Comparison table with AzonPress, follow the steps with the screenshots below –</p><p>First, go to <strong>Amazon Comparisons</strong> from the <strong>WordPress Sidebar</strong> or <strong>Comparison Tables</strong> from the <strong>Amazon</strong> dropdown in the top right corner of the <strong>AzonPress Navbar</strong>.</p><p>Now, select the desired <strong>Table</strong> you want to customize and click on the <strong>Pencil Icon</strong>.</p><p>If you do not have any existing <strong>Comparison Tables</strong>, you can <strong>create a new Comparison Table</strong>.</p><p><img src="'+a+'" alt="Desired Comparison Table"></p><p>Now, you can see that your desired product table has been opened where you will find three major settings options. These are:</p><ul><li>Compared Rows</li><li>Appearance Settings</li><li>Compared Products</li></ul><p><img src="'+r+'" alt="Opened Table with three major option"></p><h3 id="here-is-a-brief-explanation-of-all-the-settings-options-on-the-pop-up-page-given-below-–" tabindex="-1">Here is a brief explanation of all the settings options on the pop-up page given below – <a class="header-anchor" href="#here-is-a-brief-explanation-of-all-the-settings-options-on-the-pop-up-page-given-below-–" aria-label="Permalink to &quot;Here is a brief explanation of all the settings options on the pop-up page given below –&quot;">​</a></h3><h3 id="compared-rows" tabindex="-1">Compared Rows <a class="header-anchor" href="#compared-rows" aria-label="Permalink to &quot;Compared Rows&quot;">​</a></h3><p>Compared rows describe the product information that is directly fetched from Amazon product metadata. Every row has a list of <strong>dropdown</strong> options to <strong>change</strong> the <strong>value</strong> of that <strong>Row</strong>.</p><p>If you want to <strong>change</strong>, you can do it by clicking the <strong>Arrow Icon</strong> and choosing the appropriate one that suits your needs. You can also <strong>change</strong> the <strong>value</strong> of the <strong>column</strong> as well.</p><p><img src="'+i+'" alt="Dropdown list of each row"></p><p>You can move rows up and down using the <strong>Drag and Drop</strong> button. You can also hide and unhide rows using the orange <strong>Toggle</strong> button.</p><p>You can <strong>add</strong> as many rows as you want by clicking the <strong>+ Add New Row</strong> button and <strong>delete</strong> any existing row by clicking the <strong>Trash Icon</strong>.</p><p><img src="'+p+'" alt="Drag Drop Add new row and Delete buttons"></p><h3 id="appearance-settings" tabindex="-1">Appearance settings <a class="header-anchor" href="#appearance-settings" aria-label="Permalink to &quot;Appearance settings&quot;">​</a></h3><p>From the appearance settings in the top right corner, you have <strong>two</strong> more <strong>options for showing</strong> the <strong>Table Title</strong> and <strong>Table Description</strong> in the <strong>front end</strong>.</p><p>To learn about customizing tables through Appearance Settings in detail, read this <a href="/guide/miscellaneous/appearance-settings.html">Documentation</a>.</p><p><img src="'+g+'" alt="Appearance Setting and its Two options"></p><h3 id="compared-products" tabindex="-1">Compared Products <a class="header-anchor" href="#compared-products" aria-label="Permalink to &quot;Compared Products&quot;">​</a></h3><p>In the compared products section, you will see the products you added to your comparison table. Here, you can <strong>manually edit</strong> the information of your comparison table for an individual product.</p><p>To do this, go to the <strong>desired product</strong> you want to edit and click on the <strong>Pencil Icon</strong> and a popup page will appear.</p><p>Also, you can add more products by clicking the <strong>+ Add Product</strong> button and delete any products by clicking the <strong>Trash</strong> icon.</p><p><img src="'+c+'" alt="Compared Products setting"></p><p>Here, you will get a list of dropdown items that will allow you to change the default value of a row inside a product.</p><p>Now you can <strong>change</strong> the <strong>default value</strong> of your <strong>product row</strong> by clicking the <strong>Arrow Icon</strong> and choosing the value that suits your needs.</p><p>If you want to highlight a specific product in the comparison table click on <strong>Show More Options</strong> and it will open up with a <strong>Featured Text</strong> input field.</p><p><img src="'+l+'" alt="Edit Compare Product popup page"></p><p>Now, write a text into the <strong>Featured Text</strong> field that you want to show, e.g., Recommended, Best Pick.</p><p>Then, give it a <strong>Primary Color</strong>, so the column stands out from others, and you can ensure better user engagement. To set a different text color to the heading, use the <strong>Secondary Color</strong>.</p><p>Once you are done, press the <strong>Update</strong> button to save all the changes. If you don&#39;t want to save simply press the <strong>Close</strong> button.</p><p><img src="'+d+'" alt="Show more options for highlighting the products"></p><p>Once you complete all the customization, click the <strong>Update</strong> or <strong>Update Setting</strong> button, and your tables will be ready to display.</p><p>You can see the preview of your table by clicking the <strong>Preview</strong> button as well.</p><p>Additionally, to do any custom design in your table, press the <strong>Custom CSS</strong> button.</p><p>You can also <strong>change the Table name</strong> anytime by clicking the <strong>Pencil Icon</strong> right next to the table name in the top left corner.</p><p><img src="'+u+'" alt="Update Preview button"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',43)])])}const z=t(h,[["render",m]]);export{C as __pageData,z as default};
